let temperatura = (Math.random() * (50 - 20) + 20).toFixed(0);

let humedad = (Math.random() * (80 - 40) + 40).toFixed(0);

let estado = Math.random() < 0.5;


msg.payload = {
    "temperatura": temperatura,
    "humedad": parseInt(humedad), 
    "estado": estado
};

return msg;

const NAME = 'JOSE ALEXANDER RODRIGUEZ ORDOÑEZ';
const DOB = '2005-02-10';
const payload = { name: NAME, fecha_nacimiento: DOB};
const msgINF = { payload: JSON.stringify(payload), topic: 'playa/agua/pato/inf' };
return msgINF;

// --- 1. OBTENER ESTADO ANTERIOR (O INICIALIZAR) ---
let celdas = flow.get("celdas") || [
    { id: 1, estado: "parada", unid_ok_hora: 0, unid_ok_total_turno: 0, tiempo_ciclo: 10, utilizacion: 0, tiempo_espera: 0, horas_trabajadas: 0 },
    { id: 2, estado: "parada", unid_ok_hora: 0, unid_ok_total_turno: 0, tiempo_ciclo: 12, utilizacion: 0, tiempo_espera: 0, horas_trabajadas: 0 },
    { id: 3, estado: "parada", unid_ok_hora: 0, unid_ok_total_turno: 0, tiempo_ciclo: 8, utilizacion: 0, tiempo_espera: 0, horas_trabajadas: 0 },
    { id: 4, estado: "parada", unid_ok_hora: 0, unid_ok_total_turno: 0, tiempo_ciclo: 10, utilizacion: 0, tiempo_espera: 0, horas_trabajadas: 0 },
    { id: 5, estado: "parada", unid_ok_hora: 0, unid_ok_total_turno: 0, tiempo_ciclo: 15, utilizacion: 0, tiempo_espera: 0, horas_trabajadas: 0 }
];
let estado_sim = flow.get("estado_sim") || { hora_turno: 0, num_turno: 1, horas_totales: 0 };
let chart_data = flow.get("chart_data") || { labels: [], datasets: [{ label: "Producción", data: [] }] };

// --- 2. OBTENER PARÁMETROS DEL DASHBOARD ---
let staffing = flow.get("staffing") || 3;
let meta_hora_por_celda = flow.get("meta_hora") || 5;

// --- 3. AVANZAR SIMULACIÓN 1 HORA ---
estado_sim.hora_turno++;
estado_sim.horas_totales++;

let produccion_total_hora = 0;
let produccion_total_turno_acumulada = 0;

// --- 4. SIMULACIÓN POR CELDA (Flujo, KPIs) ---
for (let i = 0; i < celdas.length; i++) {
    let celda = celdas[i];

    // 4.1. Reasignación de Personal (Ampliación "Qué-pasa-si")
    if (i < staffing) {
        // Celda TIENE personal.

        // 4.2. Simulación Cuello de Botella (Objetivo)
        // Celda 2 depende de Celda 1.
        if (celda.id === 2 && celdas[0].estado !== 'trabajando') {
            celda.estado = 'esperando';
            celda.tiempo_espera += 1; // KPI: Tiempos de espera
            celda.unid_ok_hora = 0;
        } 
        // 4.3. Simulación de Falla Aleatoria (para celdas que no están esperando)
        else if (celda.estado !== 'esperando') {
            let rand = Math.random();
            if (rand < 0.85) { // 85% chance de trabajar
                celda.estado = 'trabajando';
                // Calcular producción de la hora
                celda.unid_ok_hora = Math.floor(60 / celda.tiempo_ciclo);
                celda.unid_ok_total_turno += celda.unid_ok_hora;
                celda.horas_trabajadas += 1;
            } else { // 15% chance de falla
                celda.estado = 'parada';
                celda.unid_ok_hora = 0;
            }
        }
    } else {
        // Celda NO tiene personal
        celda.estado = 'sin_personal';
        celda.unid_ok_hora = 0;
    }

    // 4.4. Calcular KPIs de Celda (Variables)
    // Prevenir división por cero en el primer tick del reseteo
    if (estado_sim.hora_turno > 0) {
        celda.utilizacion = (celda.horas_trabajadas / estado_sim.hora_turno) * 100; // KPI: Utilización
    } else {
        celda.utilizacion = 0;
    }
    produccion_total_turno_acumulada += celda.unid_ok_total_turno;
    produccion_total_hora += celda.unid_ok_hora;
}

// --- 5. PREPARAR SALIDAS (Dashboard) ---

// Salida 1: Datos para el Grid de Celdas (se envía siempre)
let msg_grid = { payload: celdas };

// Salida 2: Datos para la Tabla Comparativa (se envía siempre)
let meta_hora_total_staffed = meta_hora_por_celda * staffing;
let msg_tabla = { 
    payload: {
        hora: estado_sim.hora_turno,
        turno: estado_sim.num_turno,
        staffing: staffing,
        meta_hora: meta_hora_total_staffed,
        real_hora: produccion_total_hora,
        meta_turno_acum: meta_hora_total_staffed * estado_sim.hora_turno,
        real_turno_acum: produccion_total_turno_acumulada
    }
};

let msg_turno_fin = null;

// --- 6. AGREGACIÓN POR TURNO (Flujo) ---
if (estado_sim.hora_turno >= 8) { // Asumimos turno de 8 horas
    let meta_total_turno = meta_hora_total_staffed * 8;
    let real_total_turno = produccion_total_turno_acumulada;
    let cumplimiento = 0;
    if (meta_total_turno > 0) {
        cumplimiento = (real_total_turno / meta_total_turno) * 100;
    }

    // 6.1. Preparar Salida 3: Datos de fin de turno (Gráfico y Alerta)
    msg_turno_fin = {
        payload: {
            turno: estado_sim.num_turno,
            meta: meta_total_turno,
            real: real_total_turno,
            cumplimiento: cumplimiento,
            // Mensaje para la alerta
            alerta_msg: cumplimiento < 90 ? 
                `ALERTA: Desviación en Turno ${estado_sim.num_turno}. Cumplimiento: ${cumplimiento.toFixed(1)}%` : 
                `Turno ${estado_sim.num_turno} OK. Cumplimiento: ${cumplimiento.toFixed(1)}%`,
            // Flag para el switch de alerta
            hubo_desviacion: cumplimiento < 90
        }
    };

    // 6.2. Actualizar datos históricos del gráfico
    chart_data.datasets[0].data.push(real_total_turno);
    chart_data.labels.push(`T${estado_sim.num_turno}`);

    // Mantener solo los últimos 10 turnos
    if (chart_data.datasets[0].data.length > 10) {
        chart_data.datasets[0].data.shift();
        chart_data.labels.shift();
    }

    // 6.3. Resetear para el siguiente turno
    estado_sim.hora_turno = 0;
    estado_sim.num_turno++;
    for (let celda of celdas) {
        celda.unid_ok_total_turno = 0;
        celda.horas_trabajadas = 0;
        celda.tiempo_espera = 0;
        celda.utilizacion = 0;
    }
}

// --- 7. GUARDAR ESTADO PARA PRÓXIMO TICK ---
flow.set("celdas", celdas);
flow.set("estado_sim", estado_sim);
flow.set("chart_data", chart_data);

// Retornar mensajes a las 3 salidas del nodo
return [ msg_grid, msg_tabla, msg_turno_fin ];

