// Lee los datos históricos del gráfico guardados en el contexto
let chartData = flow.get("chart_data") || { labels: [], datasets: [{ label: "Producción", data: [] }] };

// IMPORTANTE: ui-chart necesita este formato específico
msg.payload = [];

// Crear un array de objetos con x (label) e y (valor)
for (let i = 0; i < chartData.labels.length; i++) {
    msg.payload.push({
        x: chartData.labels[i],
        y: chartData.datasets[0].data[i]
    });
}

// Establecer el topic para identificar la serie
msg.topic = "Producción";

return msg;
